        ExecutionConfig executionConfig = new ExecutionConfig();
        CloseableRegistry closeStreamOnCancelRegistry = new CloseableRegistry();

        Map<String, PartitionableListState<?>> registeredOperatorStates = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> registeredBroadcastStates = new HashMap<>();
        Map<String, PartitionableListState<?>> accessedStatesByName = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> accessedBroadcastStatesByName = new HashMap<>();

        SnapshotStrategyRunner<OperatorStateHandle, ?> snapshotStrategyRunner = 
            new SnapshotStrategyRunner<OperatorStateHandle, Object>() {
                public Object snapshot(long checkpointId, long timestamp, CheckpointStreamFactory streamFactory, CheckpointOptions checkpointOptions) {
                    return null;
                }
            };

        DefaultOperatorStateBackend backend = new DefaultOperatorStateBackend(
            executionConfig,
            closeStreamOnCancelRegistry,
            registeredOperatorStates,
            registeredBroadcastStates,
            accessedStatesByName,
            accessedBroadcastStatesByName,
            snapshotStrategyRunner
        );

        backend.dispose();
    }

    private static class PartitionableListState<T> implements ListState<T> {
        public void clear() {}
        public Iterable<T> get() { return null; }
