        public Iterable<Map.Entry<K, V>> immutableEntries() { return null; }
        public boolean isEmpty() { return false; }
    }

    private static class SnapshotStrategyRunner<T, R> {
        public R snapshot(long checkpointId, long timestamp, CheckpointStreamFactory streamFactory, CheckpointOptions checkpointOptions) {
            return null;
        }
    }

    private interface CheckpointStreamFactory {}

    private static class CheckpointOptions {}

    private static class OperatorStateHandle {}
}

