package org.apache.flink.streaming.api.operators;

import org.apache.flink.core.fs.CloseableRegistry;
import org.apache.flink.runtime.state.OperatorStateHandle;
import org.apache.flink.util.AbstractAutoCloseableRegistry;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.InputStream;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.Map;

import static org.mockito.Mockito.when;

public class OperatorStateStreamIteratorhasNext_IOUtilscloseQuietlyFikaTest {

    @Test
    public void testHasNextInvokesCloseQuietly() throws Exception {
        // Create mock dependencies
        CloseableRegistry closableRegistry = Mockito.mock(CloseableRegistry.class);
        Iterator<OperatorStateHandle> stateHandleIterator = Mockito.mock(Iterator.class);

        // Create mock OperatorStateHandle with required state
        OperatorStateHandle stateHandle = Mockito.mock(OperatorStateHandle.class);
        OperatorStateHandle.StateMetaInfo metaInfo = Mockito.mock(OperatorStateHandle.StateMetaInfo.class);

        // Setup mock behavior to trigger the path
        when(stateHandleIterator.hasNext())
            .thenReturn(true)  // First call in while loop
            .thenReturn(false); // Second call to exit loop

        when(stateHandleIterator.next()).thenReturn(stateHandle);

        // Create state name to partition offsets map
        Map<String, OperatorStateHandle.StateMetaInfo> stateMap = 
            Collections.singletonMap("testState", metaInfo);
        when(stateHandle.getStateNameToPartitionOffsets()).thenReturn(stateMap);

        // Setup metaInfo to return non-empty offsets
        long[] offsets = new long[]{1L, 2L, 3L};
        when(metaInfo.getOffsets()).thenReturn(offsets);

        // Create the iterator using reflection since it's an inner class
        StreamTaskStateInitializerImpl outerInstance = new StreamTaskStateInitializerImpl();

        // Create the inner class instance using reflection
        java.lang.reflect.Constructor<?> constructor = 
            StreamTaskStateInitializerImpl.OperatorStateStreamIterator.class
                .getDeclaredConstructor(
                    StreamTaskStateInitializerImpl.class,
                    String.class,
                    Iterator.class,
                    CloseableRegistry.class
                );
        constructor.setAccessible(true);

        StreamTaskStateInitializerImpl.OperatorStateStreamIterator iterator = 
            (StreamTaskStateInitializerImpl.OperatorStateStreamIterator) constructor.newInstance(
                outerInstance,
                "testState",
                stateHandleIterator,
                closableRegistry
            );

        // Setup closableRegistry to return true for unregisterCloseable to trigger IOUtils.closeQuietly
        when(closableRegistry.unregisterCloseable(Mockito.any())).thenReturn(true);

        // Call the entry point method
        iterator.hasNext();
    }

    // Minimal implementation of outer class to instantiate inner class
    private static class StreamTaskStateInitializerImpl {
        // Empty constructor
        public StreamTaskStateInitializerImpl() {}

        // Abstract base class required for inheritance
        private abstract static class AbstractStateStreamIterator<T> 
            extends AbstractAutoCloseableRegistry<T, InputStream> 
            implements Iterator<T> {

            protected AbstractStateStreamIterator(Iterator<T> iterator, CloseableRegistry closableRegistry) {
                super(closableRegistry);
            }
        }

        // Inner class definition matching the provided structure
        private class OperatorStateStreamIterator extends AbstractStateStreamIterator<StatePartitionStreamProvider> {
            private final String stateName;
            private long[] offsets;
            private int offPos;
            private InputStream currentStream;
            private OperatorStateHandle currentStateHandle;
            private final Iterator<OperatorStateHandle> stateHandleIterator;

            OperatorStateStreamIterator(String stateName, Iterator<OperatorStateHandle> stateHandleIterator, 
                                       CloseableRegistry closableRegistry) {
                super(stateHandleIterator, closableRegistry);
                this.stateName = stateName;
                this.stateHandleIterator = stateHandleIterator;
            }

            @Override
            public boolean hasNext() {
                if ((null != offsets) && (offPos < offsets.length)) {
                    return true;
                }
                closeCurrentStream();
