package org.apache.flink.runtime.security.modules;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.runtime.security.SecurityConfiguration;
import org.apache.hadoop.conf.Configuration as HadoopConfiguration;
import org.apache.hadoop.security.Credentials;
import org.apache.hadoop.security.UserGroupInformation;
import org.junit.jupiter.api.Test;

import java.io.File;
import java.io.IOException;
import java.lang.reflect.Field;

public class HadoopModuleinstall_UserGroupInformationaddCredentialsFikaTest {

    @Test
    public void testInstallTriggersAddCredentials() throws Exception {
        // Create Flink configuration with required security options
        Configuration flinkConfig = new Configuration();
        flinkConfig.setBoolean(org.apache.flink.configuration.SecurityOptions.DELEGATION_TOKENS_ENABLED, false);

        // Create SecurityConfiguration
        SecurityConfiguration securityConfig = new SecurityConfiguration(flinkConfig);

        // Create Hadoop configuration
        HadoopConfiguration hadoopConfig = new HadoopConfiguration();

        // Create HadoopModule instance
        HadoopModule hadoopModule = new HadoopModule(securityConfig, hadoopConfig);

        // Set environment variable to trigger the path
        String tempTokenFile = createTempTokenFile();
        try {
            System.setProperty(UserGroupInformation.HADOOP_TOKEN_FILE_LOCATION, tempTokenFile);

            // Execute the entry point
            hadoopModule.install();
        } finally {
            // Clean up
            System.clearProperty(UserGroupInformation.HADOOP_TOKEN_FILE_LOCATION);
            new File(tempTokenFile).delete();
        }
    }

    private String createTempTokenFile() throws IOException {
        File tempFile = File.createTempFile("test_token", ".bin");
        tempFile.deleteOnExit();

        // Create minimal credentials that can be read by Credentials.readTokenStorageFile
        Credentials credentials = new Credentials();
        java.io.DataOutputStream dos = new java.io.DataOutputStream(
            new java.io.FileOutputStream(tempFile));
        try {
            credentials.writeTokenStorageToStream(dos);
        } finally {
            dos.close();
        }

        return tempFile.getAbsolutePath();
    }
}

