import org.mockito.Mockito;
import oshi.SystemInfo;
import oshi.hardware.GlobalMemory;
import oshi.hardware.HardwareAbstractionLayer;
import oshi.hardware.VirtualMemory;
import java.time.Duration;

class SystemResourcesMetricsInitializerinstantiateSwapMetrics_GlobalMemorygetVirtualMemoryFikaTest {

    @Test
    void testInstantiateSystemMetrics() {
        MetricGroup mockMetricGroup = Mockito.mock(MetricGroup.class);
        MetricGroup mockSystemGroup = Mockito.mock(MetricGroup.class);
        MetricGroup mockSwapGroup = Mockito.mock(MetricGroup.class);

        Mockito.when(mockMetricGroup.addGroup("System")).thenReturn(mockSystemGroup);
        Mockito.when(mockSystemGroup.addGroup("Swap")).thenReturn(mockSwapGroup);

        SystemInfo systemInfo = new SystemInfo();
        HardwareAbstractionLayer hardware = systemInfo.getHardware();
        GlobalMemory memory = hardware.getMemory();
        VirtualMemory virtualMemory = memory.getVirtualMemory();

        Mockito.when(mockSwapGroup.gauge(Mockito.anyString(), Mockito.any(Gauge.class)))
               .thenReturn(null);

        SystemResourcesMetricsInitializer.instantiateSystemMetrics(mockMetricGroup, Duration.ofSeconds(1));
    }
}

