package org.apache.flink.runtime.state;

import org.junit.jupiter.api.Test;
import java.io.ByteArrayOutputStream;
import java.io.OutputStream;
import org.apache.flink.runtime.util.NonClosingOutputStreamDecorator;
import org.xerial.snappy.SnappyFramedOutputStream;

public class StreamCompressionDecorator_SnappyStreamCompressionDecoratordecorateWithCompression_SnappyFramedOutputStreammethodFikaTest {

    @Test
    public void testDecorateWithCompression() throws Exception {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();

        SnappyStreamCompressionDecorator decorator = new SnappyStreamCompressionDecorator();
        decorator.decorateWithCompression(byteArrayOutputStream);
    }

    private static class SnappyStreamCompressionDecorator extends StreamCompressionDecorator {
        private static final int COMPRESSION_BLOCK_SIZE = 65536;
        private static final double MIN_COMPRESSION_RATIO = 0.85;

        @Override
        protected OutputStream decorateWithCompression(NonClosingOutputStreamDecorator stream) {
            return new SnappyFramedOutputStream(stream, COMPRESSION_BLOCK_SIZE, MIN_COMPRESSION_RATIO);
        }
    }
}

