class OperatorStateStreamIterator_AbstractStateStreamIteratorcloseCurrentStream_IOUtilscloseQuietlyFikaTest {

    @Test
    void testHasNextTriggersCloseCurrentStreamAndIOUtilsCloseQuietly() throws Exception {
        // Create mock dependencies
        String stateName = "testState";
        Iterator<OperatorStateHandle> mockStateHandleIterator = Mockito.mock(Iterator.class);
        CloseableRegistry mockClosableRegistry = Mockito.mock(CloseableRegistry.class);

        // Create mock OperatorStateHandle
        OperatorStateHandle mockStateHandle = Mockito.mock(OperatorStateHandle.class);
        StateMetaInfo mockMetaInfo = Mockito.mock(StateMetaInfo.class);
        long[] metaOffsets = new long[]{1L, 2L, 3L};

        // Setup mock behavior
        Mockito.when(mockStateHandleIterator.hasNext())
            .thenReturn(true)  // First call in while loop
            .thenReturn(false); // Second call to exit loop

        Mockito.when(mockStateHandleIterator.next())
            .thenReturn(mockStateHandle);

        Mockito.when(mockStateHandle.getStateNameToPartitionOffsets())
            .thenReturn(Collections.singletonMap(stateName, mockMetaInfo));

        Mockito.when(mockMetaInfo.getOffsets())
            .thenReturn(metaOffsets);

        Mockito.when(mockClosableRegistry.unregisterCloseable(Mockito.any()))
            .thenReturn(true); // Allow closeQuietly to be called

        // Create instance using reflection since OperatorStateStreamIterator is private
        StreamTaskStateInitializerImpl.OperatorStateStreamIterator iterator = 
            new StreamTaskStateInitializerImpl.OperatorStateStreamIterator(
                stateName, 
                mockStateHandleIterator, 
                mockClosableRegistry
            );

        // Set up internal state to trigger the path
        try {
            java.lang.reflect.Field offsetsField = 
                StreamTaskStateInitializerImpl.AbstractStateStreamIterator.class
                    .getDeclaredField("offsets");
            offsetsField.setAccessible(true);
            offsetsField.set(iterator, null); // Ensure offsets is null

            java.lang.reflect.Field offPosField = 
                StreamTaskStateInitializerImpl.AbstractStateStreamIterator.class
                    .getDeclaredField("offPos");
            offPosField.setAccessible(true);
            offPosField.set(iterator, 0);

            java.lang.reflect.Field currentStreamField = 
                StreamTaskStateInitializerImpl.AbstractStateStreamIterator.class
                    .getDeclaredField("currentStream");
            currentStreamField.setAccessible(true);
            // Set a mock stream to be closed
            currentStreamField.set(iterator, Mockito.mock(java.io.InputStream.class));

        } catch (Exception e) {
            // Reflection exceptions ignored for test setup
        }

        // Call the entry point - this should trigger closeCurrentStream() and IOUtils.closeQuietly()
        iterator.hasNext();
    }
}

